/* Small, one-shot motion primitives. Inline this file into an Artifact; no imports. */
function reducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function beat(elements, { staggerMs = 70 } = {}) {
  const list = Array.from(elements)
  if (reducedMotion()) {
    for (const element of list) element.dataset.beat = 'done'
    return
  }
  for (const [index, element] of list.entries()) {
    element.classList.add('motion-enter')
    element.style.animationDelay = `${index * staggerMs}ms`
    element.addEventListener('animationend', () => { element.dataset.beat = 'done' }, { once: true })
  }
}

function highlight(element) {
  if (!element) return
  if (reducedMotion()) return
  element.classList.remove('motion-highlight')
  void element.offsetWidth
  element.classList.add('motion-highlight')
}

function tween({ from, to, duration = 420, update, done }) {
  if (reducedMotion()) {
    update(to)
    done?.()
    return () => {}
  }
  const start = performance.now()
  let frame = 0
  const step = (now) => {
    const progress = Math.min(1, (now - start) / duration)
    const eased = 1 - Math.pow(1 - progress, 3)
    update(from + (to - from) * eased)
    if (progress < 1) frame = requestAnimationFrame(step)
    else done?.()
  }
  frame = requestAnimationFrame(step)
  return () => cancelAnimationFrame(frame)
}

</script>
  <script>
    const chart = document.getElementById('chart')
    const context = chart.getContext('2d')
    const summary = document.getElementById('summary')
    const playButton = document.getElementById('play')
    let amplitude = 1
    let frequency = 1.2
    let damping = 0.5
    let time = 0
    let playing = false
    let frame = 0
    let previous = 0

    function valueAt(t) {
      return amplitude * Math.exp(-damping * t) * Math.sin(2 * Math.PI * frequency * t)
    }

    function draw() {
      const style = getComputedStyle(document.documentElement)
      const ink = style.getPropertyValue('--art-ink').trim()
      const accent = style.getPropertyValue('--art-accent').trim()
      const muted = style.getPropertyValue('--art-muted').trim()
      const good = style.getPropertyValue('--art-good').trim()
      const width = chart.width
      const height = chart.height
      context.clearRect(0, 0, width, height)
      context.strokeStyle = muted
      context.globalAlpha = 0.22
      context.lineWidth = 1
      for (let y = 30; y < height; y += 40) {
        context.beginPath(); context.moveTo(0, y); context.lineTo(width, y); context.stroke()
      }
      context.globalAlpha = 1
      context.strokeStyle = accent
      context.lineWidth = 3
      context.beginPath()
      for (let x = 0; x <= width; x++) {
        const t = time - 4 + (x / width) * 4
        const y = height / 2 - valueAt(t) * (height * 0.34)
        if (x === 0) context.moveTo(x, y)
        else context.lineTo(x, y)
      }
      context.stroke()
      context.fillStyle = good
      context.beginPath(); context.arc(width - 8, height / 2 - valueAt(time) * (height * 0.34), 5, 0, Math.PI * 2); context.fill()
      context.fillStyle = ink
      context.font = '12px system-ui'
      context.fillText('now', width - 42, height / 2 - valueAt(time) * (height * 0.34) - 12)
      summary.textContent = `t = ${time.toFixed(2)} s · ${playing ? 'playing' : 'paused'}`
      parent.postMessage({ kind: 'artifact-state', state: { time, amplitude, frequency, damping } }, '*')
    }

    function tick(now) {
      if (!playing) return
      const delta = previous === 0 ? 0 : Math.min(0.05, (now - previous) / 1000)
      previous = now
      time += delta
      draw()
      frame = requestAnimationFrame(tick)
    }

    function setPlaying(next) {
      playing = next
      playButton.textContent = playing ? 'Pause' : 'Play'
      playButton.setAttribute('aria-pressed', String(playing))
      previous = 0
      if (playing) frame = requestAnimationFrame(tick)
      else cancelAnimationFrame(frame)
      draw()
    }

    function bindRange(id, label, setter) {
      const input = document.getElementById(id)
      const output = document.getElementById(label)
      input.addEventListener('input', () => {
        const value = Number(input.value)
        output.textContent = id === 'damping' ? value.toFixed(2) : value.toFixed(1)
        setter(value)
        draw()
      })
    }

    bindRange('amplitude', 'amplitude-label', value => { amplitude = value; document.getElementById('amplitude-value').textContent = value.toFixed(1) })
    bindRange('frequency', 'frequency-label', value => { frequency = value; document.getElementById('frequency-value').textContent = value.toFixed(1) })
    bindRange('damping', 'damping-label', value => { damping = value; document.getElementById('damping-value').textContent = value.toFixed(2) })
    playButton.addEventListener('click', () => { setPlaying(!playing) })
    document.getElementById('step').addEventListener('click', () => { time += 0.1; draw(); highlight(summary) })
    document.getElementById('reset').addEventListener('click', () => {
      setPlaying(false)
      time = 0
      amplitude = 1
      frequency = 1.2
      damping = 0.5
      for (const [id, value] of [['amplitude', 1], ['frequency', 1.2], ['damping', 0.5]]) {
        const input = document.getElementById(id)
        input.value = String(value)
        input.dispatchEvent(new Event('input'))
      }
      draw()
    })

    window.addEventListener('message', event => {
      if (event.source !== parent || event.data?.kind !== 'artifact-command') return
      if (event.data.command === 'play') setPlaying(true)
      else if (event.data.command === 'pause') setPlaying(false)
      else if (event.data.command === 'step') {
        time += 0.1
        draw()
        highlight(summary)
      } else if (event.data.command === 'reset') {
        document.getElementById('reset').click()
      }
    })

    draw()
    beat(document.querySelectorAll('.hero, .workspace, .timeline'))
  </script>
</body>
