    playButton.addEventListener('click', () => { setPlaying(!playing) })
    document.getElementById('step').addEventListener('click', () => { time += 0.1; draw(); highlight(summary) })
    document.getElementById('reset').addEventListener('click', () => {
      setPlaying(false)
      time = 0
      amplitude = 1
      frequency = 1.2
      damping = 0.5
      for (const [id, value] of [['amplitude', 1], ['frequency', 1.2], ['damping', 0.5]]) {
        const input = document.getElementById(id)
        input.value = String(value)
        input.dispatchEvent(new Event('input'))
      }
      draw()
    })

    window.addEventListener('message', event => {
      if (event.source !== parent || event.data?.kind !== 'artifact-command') return
      if (event.data.command === 'play') setPlaying(true)
      else if (event.data.command === 'pause') setPlaying(false)
      else if (event.data.command === 'step') {
        time += 0.1
        draw()
        highlight(summary)
      } else if (event.data.command === 'reset') {
        document.getElementById('reset').click()
      }
    })

    draw()
    beat(document.querySelectorAll('.hero, .workspace, .timeline'))
  </script>
</body>
</html>
